/**  Streamed while the assistant works on a turn. */
export type AssistantEvent = AssistantEvent_Serialize | AssistantEvent_Deserialize;

/**  Streamed while the assistant works on a turn. */
export type AssistantEvent_Deserialize = { type: "turn_started"; thread_id: string; turn_id: string; user_message: Message_Deserialize } | 
/**  Append `delta` to the assistant message `message_id` (create it on first sight). */
{ type: "text_delta"; thread_id: string; turn_id: string; message_id: string; delta: string } | 
/**  A tool row appeared or changed status. Upsert by `action.id`. */
{ type: "tool"; thread_id: string; turn_id: string; message_id: string; action: AiAction_Deserialize } | { type: "proposal"; thread_id: string; turn_id: string; message_id: string; proposal: Proposal_Deserialize } | { type: "turn_finished"; thread_id: string; turn_id: string; end: TurnEnd };

/**  Streamed while the assistant works on a turn. */
export type AssistantEvent_Serialize = { type: "turn_started"; thread_id: string; turn_id: string; user_message: Message_Serialize } | 
/**  Append `delta` to the assistant message `message_id` (create it on first sight). */
{ type: "text_delta"; thread_id: string; turn_id: string; message_id: string; delta: string } | 
/**  A tool row appeared or changed status. Upsert by `action.id`. */
{ type: "tool"; thread_id: string; turn_id: string; message_id: string; action: AiAction_Serialize } | { type: "proposal"; thread_id: string; turn_id: string; message_id: string; proposal: Proposal_Serialize } | { type: "turn_finished"; thread_id: string; turn_id: string; end: TurnEnd };

/**  Which capture stream a segment came from. */
export type AudioChannel = 
/**  The microphone: you (and the room, for in-person meetings). */
"mic" | 
/**  System output: everyone else on the call. */
"system";

export type AudioDevice = {
	id: string,
	name: string,
	is_default: boolean,
};

/**  Input levels, 0..=1 (RMS mapped to a perceptual scale). Emitted about 20 times a second while recording. */
export type AudioLevels = {
	mic: number | null,
	system: number | null,
};

/**  Who wrote a version of a note. */
export type Author = "user" | "ai";

/**  The single backend → UI event. The UI listens once and switches on `payload.type`. */
export type BackendEvent = BackendEvent_Serialize | BackendEvent_Deserialize;

/**  The single backend → UI event. The UI listens once and switches on `payload.type`. */
export type BackendEvent_Deserialize = AppEvent_Deserialize;

/**  The single backend → UI event. The UI listens once and switches on `payload.type`. */
export type BackendEvent_Serialize = AppEvent_Serialize;

export type Backlinks = {
	/**  Notes that link here. */
	linked: Mention[],
	/**  Notes that name this one's title without linking it. */
	unlinked: Mention[],
};

export type BareNote = {
	note_id: string,
	title: string,
	created_at: string,
};

export type Category = {
	id: string,
	name: string,
	position: number | null,
	collapsed: boolean,
};

/**  Where the assistant lives in the window. */
export type CilicaPlacement = 
/**  A panel on the right that pushes the note aside. */
"side_panel" | 
/**  A bar at the bottom of the page that grows into the conversation. */
"floating_bar";

export type ClaudeCodeStatus = ClaudeCodeStatus_Serialize | ClaudeCodeStatus_Deserialize;

export type ClaudeCodeStatus_Deserialize = {
	installed: boolean,
	version?: string | null,
	signed_in: boolean,
};

export type ClaudeCodeStatus_Serialize = {
	installed: boolean,
	version: string | null,
	signed_in: boolean,
};

/**  Settings for cloud engines that need more than a key. */
export type CloudSttSettings = CloudSttSettings_Serialize | CloudSttSettings_Deserialize;

/**  Settings for cloud engines that need more than a key. */
export type CloudSttSettings_Deserialize = {
	/**  Base URL of an OpenAI-compatible service, e.g. "https://api.groq.com/openai/v1". */
	base_url?: string | null,
	/**  Model name for the OpenAI-compatible service (other providers use their own default). */
	model?: string | null,
};

/**  Settings for cloud engines that need more than a key. */
export type CloudSttSettings_Serialize = {
	/**  Base URL of an OpenAI-compatible service, e.g. "https://api.groq.com/openai/v1". */
	base_url: string | null,
	/**  Model name for the OpenAI-compatible service (other providers use their own default). */
	model: string | null,
};

/**  Which lists the UI should refetch. Coarse on purpose: the UI invalidates query keys. */
export type DataScope = "notes" | "categories" | "trash" | "versions" | "transcript" | "people" | "tasks" | "proposals" | "ai_actions" | "threads" | 
/**  The swear jar's counts (coins typed or emptied by hand). */
"swear_jar" | 
/**  Settings › Import: runs and detections. */
"imports";

/**  Which date of a note a search's date range and time of day apply to. */
export type DateField = 
/**  When the meeting started (or the note was made), or when it was last edited. */
"any" | "created" | 
/**  Last edited, or any saved version from then. */
"edited" | 
/**  When the meeting started (meetings only). */
"met" | 
/**  When it was moved to Trash. */
"deleted";

/**  What to do when a meeting app is seen holding the mic. */
export type DetectMode = 
/**  Show an action toast with Record. */
"ask_first" | "auto_start";

/**  One place on this computer where a provider's data was found. */
export type DetectedLocation = {
	/**  "Neos Vault", "Anarlog on this Mac". */
	label: string,
	path: string,
	/**  Notes (documents without a transcript). */
	notes: number,
	/**  Meetings (anything with a transcript or meeting times). */
	meetings: number,
	/**  Transcripts among them. */
	transcripts: number,
	/**  Attachments (images, PDFs) that come along. */
	attachments: number,
	/**  Things found that Cilica will not import, such as Obsidian canvases. */
	unsupported: UnsupportedItem[],
};

/**  Machine-readable error class. The UI switches on this; `message` is for people. */
export type ErrorCode = "not_found" | "invalid" | "conflict" | "permission_denied" | 
/**  Something outside the app is missing: no mic, no model downloaded, no API key. */
"unavailable" | 
/**  A provider or network call failed. */
"upstream" | "cancelled" | "not_implemented" | "internal";

export type Ghostwriter = {
	/**  0..=100. */
	cilica_pct: number,
	/**  Words added across the notes counted, by you and Cilica together. */
	words: number,
};

/**  An undirected edge between two entries of `LinkGraph::nodes`. */
export type GraphEdge = {
	source: number,
	target: number,
	kind: GraphEdgeKind,
};

/**  How two nodes are joined. */
export type GraphEdgeKind = "link" | "embed" | "tag" | 
/**  The person spoke in the meeting. Read from the transcript; never written into the note. */
"transcript";

export type GraphNode = GraphNode_Serialize | GraphNode_Deserialize;

/**  What a node in the graph stands for. */
export type GraphNodeKind = "note" | 
/**  A saved person: linked by name (`[[Sam Ortiz]]`) or heard in a meeting. */
"person" | "tag" | 
/**  A link to a note that is not created yet. */
"missing";

export type GraphNode_Deserialize = {
	/**  Stable across calls: `n:<note id>`, `p:<person id>`, `t:<tag>`, `m:<title>`. */
	key: string,
	kind: GraphNodeKind,
	label: string,
	note_id?: string | null,
	note_kind?: NoteKind | null,
	category_id?: string | null,
	person_id?: string | null,
	/**  A person's colour (1–8). */
	color_index?: number | null,
	/**  How many edges touch the node in the full graph (sizes it). */
	degree: number,
	/**  When the note was created (notes only). Orders the graph's "grow" replay. */
	created_at?: string | null,
};

export type GraphNode_Serialize = {
	/**  Stable across calls: `n:<note id>`, `p:<person id>`, `t:<tag>`, `m:<title>`. */
	key: string,
	kind: GraphNodeKind,
	label: string,
	note_id: string | null,
	note_kind: NoteKind | null,
	category_id: string | null,
	person_id: string | null,
	/**  A person's colour (1–8). */
	color_index: number | null,
	/**  How many edges touch the node in the full graph (sizes it). */
	degree: number,
	/**  When the note was created (notes only). Orders the graph's "grow" replay. */
	created_at: string | null,
};

/**  The three NSHapticFeedbackManager patterns Cilica uses. */
export type HapticKind = 
/**  A dragged item snaps into place; a resize snaps to its default width. */
"alignment" | 
/**  A permission was granted. */
"generic" | 
/**  Slider detents. */
"level_change";

/**  What this computer can run, for recommending a speech model. */
export type HardwareProfile = {
	/**  Logical CPU cores. */
	cores: number,
	/**  Installed memory, whole gigabytes. */
	ram_gb: number,
	apple_silicon: boolean,
	/**  Too slow for good local transcription: suggest a cloud service. */
	suggest_cloud: boolean,
	/**
	 *  Fast enough to tell speakers apart on this computer while it records: recommend it over
	 *  the transcription service's labels.
	 */
	local_speakers: boolean,
};

